import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PriceHistory } from './price-history.entity';

@Injectable()
export class PriceHistoryService {
  constructor(
    @InjectRepository(PriceHistory)
    private readonly priceHistoryRepository: Repository<PriceHistory>,
  ) {}

  async logPriceChange(user_id: number, price: number): Promise<void> {
    await this.priceHistoryRepository.save({
      user_id,
      price,
      timestamp: new Date()
    });
  }

  async getAveragePrices(): Promise<number[]> {
    const results = await this.priceHistoryRepository.query(`
      SELECT user_id, AVG(price) AS avg_price
      FROM price_history
      GROUP BY user_id
    `);
    return results.map(result => result.avg_price);
  }
}
