```prisma
// queries.ts
import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

async function getAveragePrice(asset: string, currency: string): Promise<number> {
  const avgPrice = await prisma.priceHistory.aggregate({
    _avg: {
      price: true,
    },
    where: {
      asset,
      currency,
    },
  })

  return avgPrice._avg.price ?? 0
}

async function getRecentPrices(asset: string, currency: string): Promise<number[]> {
  const recentPrices = await prisma.priceHistory.findMany({
    take: 30,
    where: {
      asset,
      currency,
    },
    orderBy: {
      timestamp: 'desc',
    },
  })

  return recentPrices.map((p) => p.price)
}
