// Функция для отправки транзакции
async function sendSolTransaction(fromPublicKey: string, toPublicKey: string, amount: number): Promise<void> {
  const transaction = new solanaWeb3.Transaction();
  const fromAccount = await connection.getParsedAccountInfo(fromPublicKey);
  const fromPubkey = solanaWeb3.PublicKey.from(fromAccount.data.parsed.pubkey);
  const fromSigner = new solanaWeb3.Account(solanaWeb3.Buffer.from(fromAccount.data.data));

  const instruction = new solanaWeb3.SystemProgram.transfer({
