### 3. Взаимодействие с Solana
Используйте `@solana/web3.js` для взаимодействия с Solana:

```js
import { Connection, PublicKey, SystemProgram, Transaction } from '@solana/web3.js';
import { createMint, transfer } from '@solana/spl-token';

const connection = new Connection('https://api.devnet.solana.com');

async function mintToken(mintPublicKey, recipientPublicKey, amount) {
  const mint = new PublicKey(mintPublicKey);
  const recipient = new PublicKey(recipientPublicKey);

  const transaction = new Transaction().add(
    SystemProgram.transfer({
      fromPubkey: new PublicKey(process.env.PRIVATE_KEY),
      toPubkey: recipient,
      lamports: amount * 1e9, // Convert to lamports
    }),
    createMint(
      connection,
      mint,
      recipient,
      new PublicKey(process.env.PRIVATE_KEY),
      6
    )
  );

  const signature = await connection.sendTransaction(transaction, [
    new PublicKey(process.env.PRIVATE_KEY),
  ]);

  console.log(`Transaction confirmed at https://explorer.solana.com/tx/${signature}`);
}

async function transferToken(mintPublicKey, recipientPublicKey, amount) {
  const mint = new PublicKey(mintPublicKey);
  const recipient = new PublicKey(recipientPublicKey);

  const transaction = new Transaction().add(
    transfer(
      connection,
      mint,
      recipient,
      new PublicKey(process.env.PRIVATE_KEY),
      amount * 1e9, // Convert to lamports
    )
  );

  const signature = await connection.sendTransaction(transaction, [
    new PublicKey(process.env.PRIVATE_KEY),
  ]);

  console.log(`Transaction confirmed at https://explorer.solana.com/tx/${signature}`);
}
```

