### 5. **Пример Consent Management:**
```js
function checkConsent() {
  const consentKey = 'onboarding_consent';
  const consentValue = localStorage.getItem(consentKey);

  if (consentValue === 'true') {
    return true;
  } else {
    return false;
  }
}

function requestConsent() {
  const consentKey = 'onboarding_consent';
  const consentValue = localStorage.getItem(consentKey);

  if (consentValue === 'false') {
    // Показать диалог с запросом согласия
    const result = confirm('Do you want to allow analytics tracking?');

    if (result) {
      localStorage.setItem(consentKey, 'true');
      return true;
    } else {
      localStorage.setItem(consentKey, 'false');
      return false;
    }
  } else {
    return consentValue === 'true';
  }
}

function trackOnboardingEvent(eventName) {
  if (requestConsent()) {
    if (firebase.analytics().isSupported()) {
      firebase.analytics().setAnalyticsCollectionEnabled(true);
      firebase.analytics().logEvent(eventName);
      firebase.analytics().setAnalyticsCollectionEnabled(false);
    }
  }
}
```

