#### Пример Кода:
```js
async function calculateCommissionInEuro(transactionAmount, currency) {
  const commissionRate = 0.001; // 0.1%
  const exchangeRate = await fetchExchangeRate(currency); // Функция для получения курса валюты
  const euroAmount = transactionAmount * commissionRate * exchangeRate;
  return euroAmount;
}

async function fetchExchangeRate(currency) {
  const response = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=ethereum&vs_currencies=${currency}`);
  const data = await response.json();
  return data.ethereum[currency];
}

