  useEffect(() => {
    const fetchData = async () => {
      try {
        const data = await getLocalData();
        setLocalData(data);
      } catch (error) {
        console.error('Error fetching local data:', error);
      }
    };

    fetchData();
  }, []);

  return (
    <div>
      {localData ? (
        <div>
          {/* Отображение локальных данных */}
          <h1>Current Balance: {localData.balance}</h1>
          <h2>Latest Transactions: {localData.transactions.join(', ')}</h2>
        </div>
      ) : (
        <p>Loading...</p>
      )}
    </div>
  );
}

export default App;
```

#### 2. **Обновление При Соединении:**
```js
import { useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { fetchRemoteData } from './utils'; // Функция для получения удаленных данных

function App() {
  const [localData, setLocalData] = useState(null);
  const [remoteData, setRemoteData] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const localData = await getLocalData();
        setLocalData(localData);

        if (navigator.onLine) {
          const remoteData = await fetchRemoteData();
          setRemoteData(remoteData);
        }
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };

    fetchData();
  }, [navigator.onLine]);

  useEffect(() => {
    const handleOnline = () => {
      if (navigator.onLine) {
        fetchRemoteData().then(setRemoteData);
      }
    };

    window.addEventListener('online', handleOnline);
    return () => window.removeEventListener('online', handleOnline);
  }, []);

  return (
    <div>
      {localData ? (
        <div>
          {/* Отображение локальных данных */}
          <h1>Current Balance: {localData.balance}</h1>
          <h2>Latest Transactions: {localData.transactions.join(', ')}</h2>
        </div>
      ) : (
        <p>Loading...</p>
      )}

      {remoteData ? (
        <div>
          {/* Отображение удаленных данных */}
          <h1>Updated Balance: {remoteData.balance}</h1>
          <h2>Updated Transactions: {remoteData.transactions.join(', ')}</h2>
        </div>
      ) : (
        <p>Loading...</p>
      )}
    </div>
  );
}

export default App;
```

