```javascript
import { prisma } from './db'; // Ваш клиент базы данных
import { generateRandomString, hashPassword, sendEmail } from './utils'; // Ваши вспомогательные функции

async function sendResetPasswordEmail(email) {
  const resetToken = generateRandomString(32); // Генерация случайного токена
  const resetLink = `${process.env.RESET_PASSWORD_URL}?token=${resetToken}`;

  try {
    await sendEmail(email, resetLink); // Отправка электронного письма
    console.log(`Email sent to ${email} with reset link`);
  } catch (error) {
    console.error(`Failed to send email to ${email}:`, error);
  }
}

async function storeResetToken(token, userId) {
  const resetTokenRecord = {
    token,
    userId,
    createdAt: new Date(),
    expiresAt: new Date(Date.now() + 3600000) // 1 час
  };

  await prisma.resetToken.create({ data: resetTokenRecord });
}

async function validateResetToken(token) {
  const resetTokenRecord = await prisma.resetToken.findFirst({
    where: {
      token,
      expiresAt: { gt: new Date() }
    }
  });

  if (!resetTokenRecord) {
    throw new Error('Invalid or expired reset token');
  }

  return resetTokenRecord.userId;
}

async function resetPassword(userId, newPassword) {
  const user = await prisma.user.update({
    where: { id: userId },
    data: { password: hashPassword(newPassword) }
  });

  if (!user) {
    throw new Error('User not found');
  }

  // Удаление записи о токене восстановления
  await prisma.resetToken.deleteMany({ where: { userId } });
}

