    text: `Чтобы восстановить пароль, перейдите по этой ссылке: https://yourapp.com/reset-password?key=${resetToken}`
  };

  await transporter.sendMail(mailOptions);
}

// Функция для обработки запроса на восстановление пароля
app.post('/reset-password-request', async (req, res) => {
  const { email } = req.body;

  try {
    const user = await User.findOne({ email });
    if (!user) {
      return res.status(400).json({ message: 'Пользователь не найден' });
    }

    const resetToken = generateResetToken();
    await User.updateOne({ email }, { $set: { resetToken } });

    await sendResetEmail(email, resetToken);

    res.json({ message: 'Ссылка на восстановление пароля отправлена на ваш email' });
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Ошибка при обработке запроса' });
