  try {
    const user = await User.findOne({ email, resetToken });
    if (!user) {
      return res.status(400).json({ message: 'Пользователь или ключ не найдены' });
    }

    await User.updateOne({ email, resetToken }, { $set: { password: newPassword } });
    await User.updateOne({ email, resetToken }, { $set: { resetToken: null } });

    res.json({ message: 'Пароль успешно изменен' });
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Ошибка при обработке запроса' });
  }
});

