import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class ConsentService {
  constructor(private readonly configService: ConfigService) {}

  async saveConsentStatus(address: string, consent: boolean): Promise<void> {
    // Сохранение статуса согласия в базе данных
    const client = await pool.connect();
    try {
      await client.query(
        'INSERT INTO consents (address, consent) VALUES ($1, $2) ON CONFLICT (address) DO UPDATE SET consent = $2',
        [address, consent]
      );
    } finally {
      client.release();
    }
  }

  async getConsentStatus(address: string): Promise<boolean> {
    // Получение статуса согласия из базы данных
    const client = await pool.connect();
    try {
      const result = await client.query('SELECT consent FROM consents WHERE address = $1', [address]);
      return result.rows[0]?.consent ?? false;
    } finally {
      client.release();
    }
  }
}
```

