```jsx
import { useEffect, useState } from 'react';

function useTranslation(key, language) {
  const [translation, setTranslation] = useState('');

  useEffect(() => {
    const storedTranslation = localStorage.getItem(`${key}_${language}`);
    if (storedTranslation) {
      setTranslation(storedTranslation);
    } else {
      fetchTranslation(key, language).then(setTranslation);
    }
  }, [key, language]);

  return translation;
}

async function fetchTranslation(key, language) {
  const response = await fetch(`http://your-backend/api/translations/${key}/${language}`);
  const data = await response.json();
  return data.value;
}

// Пример использования
